public static class ShipmentEndpoints
{
    public static void MapShipmentApi(this WebApplication app)
    {
        var group = app.MapGroup("api/shipments").RequireAuthorization();

        group.MapGet("/", async (string? status, string? search, IShipmentService svc) =>
            Results.Ok(await svc.GetShipmentsAsync(status, search)));

        group.MapGet("/{id:int}", async (int id, IShipmentService svc) =>
        {
            var shipment = await svc.GetShipmentByIdAsync(id);
            return shipment is null ? Results.NotFound() : Results.Ok(shipment);
        });

        group.MapGet("/track/{trackingNumber}", async (string trackingNumber, IShipmentService svc) =>
        {
            var shipment = await svc.GetShipmentByTrackingNumberAsync(trackingNumber);
            return shipment is null ? Results.NotFound() : Results.Ok(shipment);
        }).AllowAnonymous();

        group.MapPost("/", async (ShipmentDto dto, IShipmentService svc) =>
        {
            var created = await svc.CreateShipmentAsync(dto);
            return Results.Created($"api/shipments/{created.Id}", created);
        });

        group.MapPut("/{id:int}", async (int id, ShipmentDto dto, IShipmentService svc) =>
        {
            dto.Id = id;
            var updated = await svc.UpdateShipmentAsync(dto);
            return Results.Ok(updated);
        });

        group.MapDelete("/{id:int}", async (int id, IShipmentService svc) =>
        {
            await svc.DeleteShipmentAsync(id);
            return Results.NoContent();
        });
    }
}

