@page "/track/{TrackingNumber}"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services

<PageTitle>Track Shipment</PageTitle>

<h2>📍 Shipment Tracking</h2>

@if (loading)
{
    <div class="d-flex justify-content-center my-5">
        <div class="spinner-border" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
    </div>
}
else if (shipment is null)
{
    <div class="alert alert-warning mt-3">
        <strong>Not found.</strong> No shipment matches tracking number <code>@TrackingNumber</code>.
    </div>
    <a href="/" class="btn btn-outline-secondary">← Back to Home</a>
}
else
{
    <div class="card shadow-sm mt-3">
        <div class="card-header d-flex justify-content-between align-items-center">
            <strong>@shipment.TrackingNumber</strong>
            <span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span>
        </div>
        <div class="card-body">
            <div class="row">
                <div class="col-md-6">
                    <dl>
                        <dt>Origin</dt>
                        <dd>@shipment.Origin</dd>
                        <dt>Destination</dt>
                        <dd>@shipment.Destination</dd>
                        <dt>Recipient</dt>
                        <dd>@shipment.RecipientName</dd>
                    </dl>
                </div>
                <div class="col-md-6">
                    <dl>
                        <dt>Shipped Date</dt>
                        <dd>@shipment.ShippedDate.ToString("MMM dd, yyyy")</dd>
                        <dt>Estimated Delivery</dt>
                        <dd>
                            <strong>@shipment.EstimatedDelivery.ToString("MMM dd, yyyy")</strong>
                            @if (shipment.Status != ShipmentStatus.Delivered)
                            {
                                var daysLeft = (shipment.EstimatedDelivery - DateTime.UtcNow).Days;
                                <span class="text-muted ms-2">
                                    (@(daysLeft > 0 ? $"{daysLeft} days away" : "due today or overdue"))
                                </span>
                            }
                        </dd>
                        @if (shipment.ActualDelivery.HasValue)
                        {
                            <dt>Actual Delivery</dt>
                            <dd>@shipment.ActualDelivery.Value.ToString("MMM dd, yyyy")</dd>
                        }
                    </dl>
                </div>
            </div>
            @if (!string.IsNullOrWhiteSpace(shipment.Description))
            {
                <p class="text-muted mb-0"><em>@shipment.Description</em></p>
            }
        </div>
    </div>

    <!-- Progress visualization -->
    <div class="card shadow-sm mt-3">
        <div class="card-body">
            <h6>Shipment Progress</h6>
            <div class="progress" style="height: 30px;">
                <div class="progress-bar @GetProgressBarClass(shipment.Status)"
                     role="progressbar"
                     style="width: @(GetProgressPercent(shipment.Status))%"
                     aria-valuenow="@GetProgressPercent(shipment.Status)"
                     aria-valuemin="0" aria-valuemax="100">
                    @shipment.Status
                </div>
            </div>
            <div class="d-flex justify-content-between mt-1 small text-muted">
                <span>Pending</span>
                <span>Picked Up</span>
                <span>In Transit</span>
                <span>Out for Delivery</span>
                <span>Delivered</span>
            </div>
        </div>
    </div>

    <a href="/" class="btn btn-outline-secondary mt-3">← Track Another</a>
}

@code {
    [Parameter] public string TrackingNumber { get; set; } = "";
    [Inject] private IShipmentService ShipmentService { get; set; } = default!;

    private ShipmentDto? shipment;
    private bool loading = true;

    protected override async Task OnParametersSetAsync()
    {
        loading = true;
        shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(TrackingNumber);
        loading = false;
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-info text-dark",
        ShipmentStatus.Delayed => "bg-danger",
        ShipmentStatus.Returned => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-warning text-dark",
        _ => "bg-secondary"
    };

    private static string GetProgressBarClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delayed => "bg-danger",
        ShipmentStatus.Returned => "bg-secondary",
        ShipmentStatus.Delivered => "bg-success",
        _ => "bg-primary"
    };

    private static int GetProgressPercent(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => 10,
        ShipmentStatus.PickedUp => 30,
        ShipmentStatus.InTransit => 55,
        ShipmentStatus.OutForDelivery => 80,
        ShipmentStatus.Delivered => 100,
        ShipmentStatus.Delayed => 55,
        ShipmentStatus.Returned => 100,
        _ => 0
    };
}

@page "/shipments"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Microsoft.AspNetCore.Authorization.Authorize]

<PageTitle>Shipments Dashboard</PageTitle>

<div class="d-flex justify-content-between align-items-center mb-3">
    <h2>📋 Shipments Dashboard</h2>
    <button class="btn btn-success" @onclick="ShowCreateForm">+ New Shipment</button>
</div>

<!-- Filters -->
<div class="row g-2 mb-3">
    <div class="col-md-4">
        <input type="text" class="form-control" placeholder="Search by tracking #, destination, recipient..."
               @bind="searchTerm" @bind:event="oninput" @onkeydown="HandleSearchKeyDown" />
    </div>
    <div class="col-md-3">
        <select class="form-select" @bind="statusFilter">
            <option value="">All Statuses</option>
            @foreach (var s in Enum.GetValues<ShipmentStatus>())
            {
                <option value="@s">@s</option>
            }
        </select>
    </div>
    <div class="col-md-2">
        <button class="btn btn-primary w-100" @onclick="LoadShipments">Filter</button>
    </div>
</div>

@if (loading)
{
    <div class="d-flex justify-content-center my-5">
        <div class="spinner-border" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
    </div>
}
else if (shipments.Count == 0)
{
    <div class="alert alert-info">No shipments found.</div>
}
else
{
    <div class="table-responsive">
        <table class="table table-hover table-striped">
            <thead class="table-dark">
                <tr>
                    <th>Tracking #</th>
                    <th>Origin</th>
                    <th>Destination</th>
                    <th>Recipient</th>
                    <th>Status</th>
                    <th>Est. Delivery</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var s in shipments)
                {
                    <tr>
                        <td><code>@s.TrackingNumber</code></td>
                        <td>@s.Origin</td>
                        <td>@s.Destination</td>
                        <td>@s.RecipientName</td>
                        <td><span class="badge @GetBadgeClass(s.Status)">@s.Status</span></td>
                        <td>@s.EstimatedDelivery.ToString("MMM dd, yyyy")</td>
                        <td>
                            <button class="btn btn-sm btn-outline-primary me-1" @onclick="() => EditShipment(s)">Edit</button>
                            <button class="btn btn-sm btn-outline-danger" @onclick="() => ConfirmDelete(s)">Delete</button>
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

<!-- Create/Edit Modal -->
@if (showForm)
{
    <div class="modal d-block" tabindex="-1" style="background-color: rgba(0,0,0,0.5);">
        <div class="modal-dialog modal-lg">
            <div class="modal-content">
                <div class="modal-header">
                    <h5 class="modal-title">@(editingShipment.Id == 0 ? "New Shipment" : "Edit Shipment")</h5>
                    <button type="button" class="btn-close" @onclick="CloseForm"></button>
                </div>
                <div class="modal-body">
                    @if (!string.IsNullOrEmpty(formError))
                    {
                        <div class="alert alert-danger">@formError</div>
                    }
                    <div class="row g-3">
                        <div class="col-md-6">
                            <label class="form-label">Origin</label>
                            <input type="text" class="form-control" @bind="editingShipment.Origin" />
                        </div>
                        <div class="col-md-6">
                            <label class="form-label">Destination</label>
                            <input type="text" class="form-control" @bind="editingShipment.Destination" />
                        </div>
                        <div class="col-md-6">
                            <label class="form-label">Recipient Name</label>
                            <input type="text" class="form-control" @bind="editingShipment.RecipientName" />
                        </div>
                        <div class="col-md-6">
                            <label class="form-label">Status</label>
                            <select class="form-select" @bind="editingShipment.Status">
                                @foreach (var s in Enum.GetValues<ShipmentStatus>())
                                {
                                    <option value="@s">@s</option>
                                }
                            </select>
                        </div>
                        <div class="col-md-6">
                            <label class="form-label">Estimated Delivery</label>
                            <input type="date" class="form-control" @bind="editingShipment.EstimatedDelivery" />
                        </div>
                        <div class="col-md-6">
                            <label class="form-label">Description</label>
                            <input type="text" class="form-control" @bind="editingShipment.Description" />
                        </div>
                    </div>
                </div>
                <div class="modal-footer">
                    <button class="btn btn-secondary" @onclick="CloseForm">Cancel</button>
                    <button class="btn btn-primary" @onclick="SaveShipment" disabled="@saving">
                        @(saving ? "Saving..." : "Save")
                    </button>
                </div>
            </div>
        </div>
    </div>
}

<!-- Delete Confirmation -->
@if (deleteTarget is not null)
{
    <div class="modal d-block" tabindex="-1" style="background-color: rgba(0,0,0,0.5);">
        <div class="modal-dialog">
            <div class="modal-content">
                <div class="modal-header">
                    <h5 class="modal-title">Confirm Delete</h5>
                    <button type="button" class="btn-close" @onclick="() => deleteTarget = null"></button>
                </div>
                <div class="modal-body">
                    <p>Delete shipment <strong>@deleteTarget.TrackingNumber</strong> to <strong>@deleteTarget.Destination</strong>?</p>
                </div>
                <div class="modal-footer">
                    <button class="btn btn-secondary" @onclick="() => deleteTarget = null">Cancel</button>
                    <button class="btn btn-danger" @onclick="DeleteShipment">Delete</button>
                </div>
            </div>
        </div>
    </div>
}

@code {
    [Inject] private IShipmentService ShipmentService { get; set; } = default!;

    private List<ShipmentDto> shipments = [];
    private bool loading = true;
    private string searchTerm = "";
    private string statusFilter = "";

    private bool showForm;
    private bool saving;
    private string formError = "";
    private ShipmentDto editingShipment = new();
    private ShipmentDto? deleteTarget;

    protected override async Task OnInitializedAsync() => await LoadShipments();

    private async Task LoadShipments()
    {
        loading = true;
        shipments = await ShipmentService.GetShipmentsAsync(statusFilter, searchTerm);
        loading = false;
    }

    private void HandleSearchKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter") _ = LoadShipments();
    }

    private void ShowCreateForm()
    {
        editingShipment = new ShipmentDto { EstimatedDelivery = DateTime.UtcNow.AddDays(7) };
        formError = "";
        showForm = true;
    }

    private void EditShipment(ShipmentDto s)
    {
        editingShipment = new ShipmentDto
        {
            Id = s.Id,
            TrackingNumber = s.TrackingNumber,
            Origin = s.Origin,
            Destination = s.Destination,
            Status = s.Status,
            ShippedDate = s.ShippedDate,
            EstimatedDelivery = s.EstimatedDelivery,
            ActualDelivery = s.ActualDelivery,
            RecipientName = s.RecipientName,
            Description = s.Description
        };
        formError = "";
        showForm = true;
