@page "/"

<PageTitle>ShipmentTracker - Home</PageTitle>

<div class="text-center mt-4">
    <h1>📦 Shipment Tracker</h1>
    <p class="lead">Track your shipments in real time.</p>
</div>

<div class="row justify-content-center mt-4">
    <div class="col-md-6">
        <div class="card shadow-sm">
            <div class="card-body">
                <h5 class="card-title">Track a Shipment</h5>
                <p class="card-text">Enter your tracking number to see the current status and estimated delivery.</p>
                <div class="input-group">
                    <input type="text" class="form-control" placeholder="e.g. SHP-20260601-100001"
                           @bind="trackingNumber" @bind:event="oninput"
                           @onkeydown="HandleKeyDown" />
                    <button class="btn btn-primary" @onclick="TrackShipment" disabled="@string.IsNullOrWhiteSpace(trackingNumber)">
                        Track
                    </button>
                </div>
            </div>
        </div>
    </div>
</div>

<AuthorizeView>
    <Authorized>
        <div class="row justify-content-center mt-4">
            <div class="col-md-6">
                <div class="card shadow-sm">
                    <div class="card-body text-center">
                        <h5 class="card-title">Dispatcher Dashboard</h5>
                        <p class="card-text">View and manage all shipments.</p>
                        <a href="shipments" class="btn btn-outline-primary">Go to Dashboard</a>
                    </div>
                </div>
            </div>
        </div>
    </Authorized>
</AuthorizeView>

@code {
    [Inject] private NavigationManager Nav { get; set; } = default!;

    private string trackingNumber = "";

    private void TrackShipment()
    {
        if (!string.IsNullOrWhiteSpace(trackingNumber))
            Nav.NavigateTo($"track/{Uri.EscapeDataString(trackingNumber.Trim())}");
    }

    private void HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter") TrackShipment();
    }
}

